请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-014

=== 用户原始指令 (query.txt) ===
上次那张卡片背景太素了，重新做一张低电卡片，背景要那种像夜空延伸出来的感觉。左边信息区显示日历日程和电量状态，电量低了橙色警告。右边动作区横向排几个可勾选的小卡片，勾完跳到系统设置里的省电、屏幕、电池优化这些。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "上次那张卡片背景太素了，重新做一张低电卡片，背景要那种像夜空延伸出来的感觉。左边信息区显示日历日程和电量状态，电量低了橙色警告。右边动作区横向排几个可勾选的小卡片，勾完跳到系统设置里的省电、屏幕、电池优化这些。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModel": {
    "value": {
      "data": {
        "calendar": {
          "items": []
        }
      },
      "power": {
        "levelText": "18%",
        "status": "电量低",
        "actionText": "设置",
        "checks": [
          {
            "label": "省电",
            "select": true
          },
          {
            "label": "屏幕",
            "select": false
          }
        ]
      },
      "asset": {
        "powerIcon": "resources/base/media/icon_save_power.png"
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "power_icon",
      "src": "resources/base/media/icon_save_power.png",
      "use": "low power icon",
      "description": "低电和省电语义图标，适合用于低电模式卡片的状态识别。",
      "bindTo": "/asset/powerIcon",
      "static": true
    }
  ]
}

